import json
import math
import statistics as st

dates = ["2024-03-04", "2024-03-05", "2024-03-06", "2024-03-07", "2024-03-08", "2024-03-11"]
closes = {
    "ACME": [50.0, 51.2, 50.6, 52.3, 53.0, 52.1],
    "BOLT": [120.0, 118.5, 119.8, 121.4, 117.9, 119.0],
}
tick = ["ACME", "BOLT"]
prices = {"dates": dates, "tickers": tick, "closes": closes}
rets = {t: [math.log(c[i] / c[i - 1]) for i in range(1, 6)] for t, c in closes.items()}
returns = {"base_date": dates[0], "dates": dates[1:], "tickers": tick, "values": rets}
w = 2
vol = {
    t: [None if i < w else st.stdev(r[i - w : i]) * math.sqrt(252) for i in range(5)]
    for t, r in rets.items()
}
vs = {"returns": returns, "window": w, "annualized": True, "values": vol}


def summ(t):
    r = rets[t]
    ar = 252 * st.mean(r)
    av = math.sqrt(252) * st.stdev(r)
    return {"ticker": t, "ann_return": ar, "ann_vol": av, "sharpe": ar / av, "last_vol": vol[t][-1]}


def dd(t):
    wealth = 1.0
    allw = [(dates[0], 1.0)]
    for d, r in zip(dates[1:], rets[t]):
        wealth *= math.exp(r)
        allw.append((d, wealth))
    peak = 1.0
    pdate = dates[0]
    best = (0.0, dates[0], dates[0])
    for d, wv in allw:
        if wv > peak:
            peak = wv
            pdate = d
        depth = wv / peak - 1
        if depth < best[0]:
            best = (depth, pdate, d)
    return {"ticker": t, "depth": best[0], "peak_date": best[1], "trough_date": best[2]}


rows = []
for t in tick:
    s = summ(t)
    d = dd(t)
    rows.append(
        {**s, "max_drawdown": d["depth"], "peak_date": d["peak_date"], "trough_date": d["trough_date"]}
    )
report = {"path": "risk_report.json", "rows": rows}
print(json.dumps({"returns": returns, "vol": vol, "summ": summ("ACME"), "dd": dd("ACME"), "report": report}, indent=1))

